class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self.options = {}
        self.voters = {}
        self.vote_count = 0

    def add_option(self, option: str) -> None:
        if option not in self.options:
            self.options[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if option not in self.options:
            raise ValueError(f"Option '{option}' does not exist.")
        if voter in self.voters:
            raise ValueError(f"Voter '{voter}' has already voted.")
        self.voters[voter] = option
        self.options[option] += 1
        self.vote_count += 1

    def winner(self) -> str | None:
        if self.vote_count < 3:
            return None
        best_option = None
        best_votes = -1
        for option, votes in self.options.items():
            if votes > best_votes:
                best_option = option
                best_votes = votes
        return best_option
